/**
 * TimeSeriesChart — lightweight SVG line / area chart with hover tooltips.
 * Story 23-12 (AC4). No external charting library: the path is generated by
 * hand and the chart scales responsively via a `viewBox`.
 */

import { useState, type JSX, type MouseEvent } from 'react';
import { EmptyState } from './EmptyState.js';

export interface TimeSeriesPoint {
  timestamp: number | string | Date;
  value: number;
}

interface TimeSeriesChartProps {
  data: TimeSeriesPoint[];
  height?: number;
  variant?: 'line' | 'area';
  /** Stroke / fill color. Defaults to a blue matching the dashboard palette. */
  color?: string;
  valueFormatter?: (value: number) => string;
  emptyMessage?: string;
  ariaLabel?: string;
  className?: string;
}

const VIEW_WIDTH = 600;
const PADDING = 8;

function toMillis(ts: number | string | Date): number {
  if (ts instanceof Date) return ts.getTime();
  if (typeof ts === 'number') return ts;
  const parsed = new Date(ts).getTime();
  return Number.isNaN(parsed) ? 0 : parsed;
}

export function TimeSeriesChart({
  data,
  height = 160,
  variant = 'line',
  color = '#3b82f6',
  valueFormatter = (v) => String(v),
  emptyMessage = 'No data for the selected range.',
  ariaLabel = 'Time series chart',
  className = '',
}: TimeSeriesChartProps): JSX.Element {
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);

  if (data.length === 0) {
    return <EmptyState title="No data" description={emptyMessage} className={className} />;
  }

  const values = data.map((d) => d.value);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = max - min || 1;
  const innerW = VIEW_WIDTH - PADDING * 2;
  const innerH = height - PADDING * 2;
  const step = data.length > 1 ? innerW / (data.length - 1) : 0;

  const coords = data.map((d, i) => {
    const x = PADDING + i * step;
    const y = PADDING + innerH - ((d.value - min) / span) * innerH;
    return { x, y };
  });

  const linePath = coords
    .map((c, i) => `${i === 0 ? 'M' : 'L'}${c.x.toFixed(2)},${c.y.toFixed(2)}`)
    .join(' ');

  const first = coords[0];
  const last = coords[coords.length - 1];
  const areaPath =
    first && last
      ? `${linePath} L${last.x.toFixed(2)},${(height - PADDING).toFixed(2)} L${first.x.toFixed(
          2,
        )},${(height - PADDING).toFixed(2)} Z`
      : '';

  const handleMove = (e: MouseEvent<HTMLDivElement>): void => {
    const rect = e.currentTarget.getBoundingClientRect();
    if (rect.width === 0 || data.length === 0) return;
    const ratio = (e.clientX - rect.left) / rect.width;
    const index = Math.round(ratio * (data.length - 1));
    setHoverIndex(Math.max(0, Math.min(data.length - 1, index)));
  };

  const hovered = hoverIndex !== null ? coords[hoverIndex] : undefined;
  const hoveredPoint = hoverIndex !== null ? data[hoverIndex] : undefined;

  return (
    <div
      data-testid="time-series-chart"
      className={`relative w-full ${className}`}
      onMouseMove={handleMove}
      onMouseLeave={() => setHoverIndex(null)}
    >
      <svg
        viewBox={`0 0 ${VIEW_WIDTH} ${height}`}
        preserveAspectRatio="none"
        className="w-full"
        style={{ height }}
        role="img"
        aria-label={ariaLabel}
      >
        {variant === 'area' && areaPath && <path d={areaPath} fill={color} fillOpacity={0.12} />}
        <path
          d={linePath}
          fill="none"
          stroke={color}
          strokeWidth={1.5}
          vectorEffect="non-scaling-stroke"
        />
        {hovered && (
          <>
            <line
              x1={hovered.x}
              y1={PADDING}
              x2={hovered.x}
              y2={height - PADDING}
              stroke={color}
              strokeWidth={1}
              strokeDasharray="3 3"
              vectorEffect="non-scaling-stroke"
              opacity={0.5}
            />
            <circle cx={hovered.x} cy={hovered.y} r={3} fill={color} />
          </>
        )}
      </svg>
      {hovered && hoveredPoint && (
        <div
          data-testid="time-series-tooltip"
          className="pointer-events-none absolute -translate-x-1/2 rounded bg-gray-900 px-2 py-1 text-xs text-white shadow"
          style={{ left: `${(hovered.x / VIEW_WIDTH) * 100}%`, top: 0 }}
        >
          <div className="font-semibold">{valueFormatter(hoveredPoint.value)}</div>
          <div className="text-gray-300">
            {new Date(toMillis(hoveredPoint.timestamp)).toLocaleString()}
          </div>
        </div>
      )}
    </div>
  );
}
